<?php $subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart));$error=$_SESSION['checkout_error']??null;unset($_SESSION['checkout_error']);$hasProduct=isset($cart['product']);$hasTraining=isset($cart['training']);$viewer=$_SESSION['user']??[]; ?>
<section class="checkout-head"><p class="site-kicker"><?= $hasTraining&&!$hasProduct?'INSCRIPTION SÉCURISÉE':'COMMANDE SÉCURISÉE' ?></p><h1><?= $hasTraining&&!$hasProduct?'Finaliser mon inscription':'Informations et paiement' ?></h1><p><?= $hasTraining&&!$hasProduct?'Aucune adresse de livraison nécessaire : votre accès est numérique.':'La livraison concerne uniquement les articles physiques de la boutique.' ?></p></section><form class="checkout-layout" method="post" action="/commande"><div class="checkout-main"><?php if($error): ?><div class="auth-error"><?= htmlspecialchars($error) ?></div><?php endif ?><div class="checkout-box checkout-form"><h2>Vos coordonnées</h2><p>Utilisées pour votre reçu<?= $hasTraining?' et votre dossier apprenant':'' ?>.</p><div class="field-grid"><label>Nom complet *<input name="name" value="<?= htmlspecialchars($viewer['name']??'') ?>" required></label><label>Email *<input type="email" name="email" value="<?= htmlspecialchars($viewer['email']??'') ?>" required></label><label>Téléphone *<input name="phone" value="<?= htmlspecialchars($viewer['phone']??'') ?>" placeholder="+225 ..." required></label><label>Entreprise<input name="company"></label></div></div><?php if($hasProduct): ?><div class="checkout-box choice-box"><h2>Réception des équipements</h2><p>Ce choix ne s’applique pas aux formations.</p><label class="choice active"><input type="radio" name="delivery" value="pickup" checked><span>⌂</span><div><strong>Retrait gratuit</strong><small>Koumassi ou Yopougon Niangon</small></div></label><label class="choice"><input type="radio" name="delivery" value="delivery"><span>▣</span><div><strong>Livraison à domicile</strong><small>Un conseiller confirmera le tarif</small></div></label></div><?php else: ?><input type="hidden" name="delivery" value="pickup"><div class="checkout-box digital-access"><span>✓</span><div><h2>Accès pédagogique numérique</h2><p>La formation sera disponible depuis votre tableau de bord. Aucun colis et aucune livraison.</p></div></div><?php endif ?><div class="checkout-box choice-box"><h2>Mode de paiement</h2><label class="choice active"><input type="radio" name="payment" value="online" checked><span>▣</span><div><strong>Mobile Money / Carte</strong><small>Validation et reçu immédiats</small></div></label><?php if($hasProduct): ?><label class="choice"><input type="radio" name="payment" value="delivery"><span>◷</span><div><strong>Payer à la livraison</strong><small>Uniquement pour les équipements physiques</small></div></label><?php endif ?></div></div><aside class="summary-card"><h2><?= $hasTraining&&!$hasProduct?'Résumé de l’inscription':'Total de la commande' ?></h2><?php foreach($cart as $key=>$item): ?><p><span><?= $key==='training'?'Formation : ':'Équipement : ' ?><?= htmlspecialchars($item['name']) ?></span><b><?= number_format($item['price']*$item['quantity'],0,',',' ') ?></b></p><?php endforeach ?><hr><p class="total"><span>Total</span><strong><?= number_format($subtotal,0,',',' ') ?> FCFA</strong></p><button class="site-btn gold wide"><?= $hasTraining&&!$hasProduct?'Confirmer et accéder à la formation':'Confirmer la commande' ?> →</button><small class="safe">En confirmant, vous acceptez les conditions applicables.</small></aside></form>
